import json
import unittest
from pathlib import Path

ROOT = Path(__file__).resolve().parents[3]
import sys
sys.path.insert(0, str(ROOT))

from components.observed_outages.work import compute


class TestObservedOutages(unittest.TestCase):
    def test_public_fixture(self):
        payload = json.loads((ROOT / "components/observed_outages/input.json").read_text())
        expected = json.loads((ROOT / "components/observed_outages/expected.json").read_text())
        self.assertEqual(compute(payload), expected)

    def test_as_of_filters_future_records(self):
        payload = {
            "queries": [{"start": 0, "end": 2, "as_of": 1, "targets": ["x"]}],
            "log": [
                ["x", 0, 1, "down"],
                ["x", 0, 5, "up"],
            ],
        }
        # Only the record seen at 1 is visible; it is down.
        self.assertEqual(compute(payload), [[["x"], ["x"]]])

    def test_same_effective_time_last_seen_wins(self):
        payload = {
            "queries": [{"start": 0, "end": 1, "as_of": 5, "targets": ["x"]}],
            "log": [
                ["x", 0, 1, "down"],
                ["x", 0, 2, "up"],
            ],
        }
        self.assertEqual(compute(payload), [[[]]])

    def test_degraded_counts_as_unavailable(self):
        payload = {
            "queries": [{"start": 0, "end": 1, "as_of": 5, "targets": ["x"]}],
